import{_ as t,a,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第四册：流利英语 · Lesson 14 The Butterfly Effect","description":"学习 第二条件句与假设距离，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 14 The Butterfly Effect","description":"学习 第二条件句与假设距离，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 第二条件句与假设距离，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 13 The search for oil","link":"/life/english/new-concept/book-4/unit-02/lesson-013"},"next":{"text":"第四册：流利英语 · Lesson 15 Secrecy in industry","link":"/life/english/new-concept/book-4/unit-02/lesson-015"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 13 The search for oil","link":"/life/english/new-concept/book-4/unit-02/lesson-013"},"next":{"text":"第四册：流利英语 · Lesson 15 Secrecy in industry","link":"/life/english/new-concept/book-4/unit-02/lesson-015"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/lesson-014.md","filePath":"life/english/new-concept/book-4/unit-02/lesson-014.md"}'),o={name:"life/english/new-concept/book-4/unit-02/lesson-014.md"};function l(r,e,s,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-lesson-14-the-butterfly-effect" tabindex="-1">第四册：流利英语 · Lesson 14 The Butterfly Effect <a class="header-anchor" href="#第四册-流利英语-·-lesson-14-the-butterfly-effect" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 14 The Butterfly Effect&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>借蝴蝶效应讨论复杂系统中初始条件与预测结果的关系，避免把比喻误读成某只蝴蝶必然造成某场风暴。训练区分假设、反事实与观测结果，理解模型中的变化不等于对真实事件的完整解释。输出时明确说明哪些条件改变、哪些条件保持不变。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>initial</td><td>/ɪˈnɪʃəl/</td><td>adj.</td><td>最初的</td><td>initial conditions</td></tr><tr><td>sensitive</td><td>/ˈsensətɪv/</td><td>adj.</td><td>敏感的</td><td>sensitive to change</td></tr><tr><td>predict</td><td>/prɪˈdɪkt/</td><td>v.</td><td>预测</td><td>predict an outcome</td></tr><tr><td>variation</td><td>/ˌveəriˈeɪʃən/</td><td>n.</td><td>变化</td><td>a small variation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>result in — 导致某结果</li><li>over time — 随着时间推移</li></ul><h2 id="语法讲解-第二条件句与假设距离" tabindex="-1">语法讲解：第二条件句与假设距离 <a class="header-anchor" href="#语法讲解-第二条件句与假设距离" aria-label="Permalink to &quot;语法讲解：第二条件句与假设距离&quot;">​</a></h2><p>If + 一般过去时，主句 would/could/might + 动词原形，可以讨论与当前现实有距离的假设或较不确定的未来情形。过去形式在这里不一定指过去时间。If we changed the initial value, the model might produce a different result. 中 might 比 would 更谨慎。反事实过去通常使用 if had done 与 would have done，不能把两个时间框架随意混合。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>If we changed the starting value slightly, the two simulations might diverge over time.</p></blockquote><p>如果我们稍微改变初始值，两次模拟可能会随时间逐渐分离。</p><p>changed 在条件句表假设；might diverge 保留结果不确定性；over time 表渐进过程。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要看到 changed 就一律解释成过去已发生；在本条件句里它表示假设距离。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 if 从句后停顿，重读 slightly 和 might；再把 might 改读 would，比较语气确定程度。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The two curves begin close together. If we altered one starting value, they might separate later. This example illustrates sensitivity, but it does not predict a particular storm.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为两个模拟结果写三句说明，提出一个变量变化假设并指出预测限制。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>把图形描述、假设实验和外推边界分别表达，避免把隐喻当成事件证明。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例是在报告已经改变了数值吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> if changed 与 might 构成假设情境。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：If the model were simpler, we ___ test it more easily.（could / can）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> could</p><p><strong>解析：</strong> 与 were 的假设条件相配。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把现在假设 if we changed 改成过去反事实条件。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if we had changed</p><p><strong>解析：</strong> 过去反事实条件采用过去完成时。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：第二条件句与假设距离。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-013">上一课</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-02/lesson-015">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=t(o,[["render",l]]);export{p as __pageData,f as default};
